void axiam_mgmt_create_webhook_request_free(axiam_mgmt_create_webhook_request_t *value) {
    if (!value) return;
    if (value->events) {
        for (size_t i = 0; i < value->events_count; i++) free(value->events[i]);
        free(value->events);
    }
    axiam_mgmt_retry_policy_free(value->retry_policy);
    axiam_sensitive_free(value->secret);
    free(value->url);
    free(value);
}

axiam_mgmt_create_webhook_request_t *axiam_mgmt_create_webhook_request_parse(const cJSON *src) {
    if (!cJSON_IsObject(src)) return NULL;
    axiam_mgmt_create_webhook_request_t *out = (axiam_mgmt_create_webhook_request_t *) calloc(1, sizeof(*out));
    if (!out) return NULL;
    const cJSON *item;
    (void) item;
    item = cJSON_GetObjectItemCaseSensitive(src, "events");
    if (cJSON_IsArray(item)) {
        size_t n = (size_t) cJSON_GetArraySize(item);
        if (n > 0) {
            out->events = (char **) calloc(n, sizeof(char *));
            if (!out->events) { axiam_mgmt_create_webhook_request_free(out); return NULL; }
            for (size_t i = 0; i < n; i++) {
                const cJSON *e = cJSON_GetArrayItem(item, (int) i);
                if (cJSON_IsString(e)) out->events[i] = axiam_strdup0(e->valuestring);
            }
            out->events_count = n;
        }
    }
    item = cJSON_GetObjectItemCaseSensitive(src, "retry_policy");
    if (cJSON_IsObject(item)) out->retry_policy = axiam_mgmt_retry_policy_parse(item);
    item = cJSON_GetObjectItemCaseSensitive(src, "secret");
    if (cJSON_IsString(item)) out->secret = axiam_sensitive_new(item->valuestring);
    item = cJSON_GetObjectItemCaseSensitive(src, "url");
    if (cJSON_IsString(item)) out->url = axiam_strdup0(item->valuestring);
    return out;
}

cJSON *axiam_mgmt_create_webhook_request_build(const axiam_mgmt_create_webhook_request_t *value) {
    if (!value) return NULL;
    cJSON *obj = cJSON_CreateObject();
    if (!obj) return NULL;
    if (value->events) {
        cJSON *arr = cJSON_AddArrayToObject(obj, "events");
        for (size_t i = 0; arr && i < value->events_count; i++)
            cJSON_AddItemToArray(arr, cJSON_CreateString(value->events[i]));
    }
    if (value->retry_policy) {
        cJSON *sub = axiam_mgmt_retry_policy_build(value->retry_policy);
        if (sub) cJSON_AddItemToObject(obj, "retry_policy", sub);
    }
    if (value->secret) {
        cJSON_AddStringToObject(obj, "secret", axiam_sensitive_reveal(value->secret));
    }
    if (value->url) {
        cJSON_AddStringToObject(obj, "url", value->url);
    }
    return obj;
}

